"use strict";
// A schema helper whose loader picks its parts with a computed require()
// specifier: scriptc cannot compile that natively, so the package runs in
// a Node island and the enum object crosses into it.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const [schema] = ["./lib/schema"].map((p) => load(p));

exports.Enum = schema.Enum;
exports.describe = schema.describe;
exports.check = schema.check;
